 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_preview = async function (action) {
    try { return await $c.data.downFile(action ?? "/discls/disclosure.do?method=searchDocumentPrint", "", ($c.util.getComponent("dma_previewReq") ? $c.util.getComponent("dma_previewReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

