/**
 * @method
 * @name fnCheckAll
 * @description fn Check All 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAll = function () {
    for (let i = 0; i < $c.util.getComponent('ipt_formProcStsCheck').length; i++) {
        $c.util.getComponent(["ipt_formProcStsCheck", "ipt_formProcStsCheck_2", "ipt_formProcStsCheck_3", "ipt_formProcStsCheck_4", "ipt_formProcStsCheck_5"][i]).checked = (String($c.util.getComponent('ipt_formProcStsAll').getValue() || "") !== "");
    }
};

/**
 * @method
 * @name fnCheckList
 * @description fn Check List 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckList = function () {
    let all_checked = true;
    for (let i = 0; i < $c.util.getComponent('ipt_formProcStsCheck').length; i++) {
        if (!(String($c.util.getComponent(["ipt_formProcStsCheck", "ipt_formProcStsCheck_2", "ipt_formProcStsCheck_3", "ipt_formProcStsCheck_4", "ipt_formProcStsCheck_5"][i]).getValue() || '') !== '')) {
            all_checked = false;
        }
    }
    $c.util.getComponent("ipt_formProcStsAll").setValue(all_checked);
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

