/**
 * @method
 * @name krxpage_pagenavigator_133_onclick
 * @description krxpage_pagenavigator_133 클릭 이벤트
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.krxpage_pagenavigator_133_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_deleteDoReq').set('pageIndex', pi);
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldods70201.krxpage_pagenavigator_133_onclick" });
    }
};
